from requests import get
from requests.exceptions import ConnectionError, ReadTimeout, ChunkedEncodingError


from taf.rfrl.procedures.resources.python.bts.utils.pretty_logger import log_debug
from taf.rfrl.procedures.resources.python.bts.utils.exceptions import ResultError
from taf.rfrl.procedures.resources.python.bts.utils.timer import wait_for


def check_if_ip_is_reachable_via_https(ip: str, timeout: int):
    """
    Checks if IP address is reachable via HTTPS protocol.
    :param ip: IP address to be checked; i.e. '192.168.255.129'
    :param timeout: time (in seconds) for IP address to become reachable
    :raises ResultError: when IP address is not reachable
    """
    log_debug(f'Checking if IP {ip} is reachable via HTTPS')

    reachable = wait_for(expected_value=True,
                         abort_if=None,
                         timeout=timeout,
                         callback=_is_ip_reachable_via_https,
                         raise_exc=False,
                         ip=ip)

    if not reachable:
        raise ResultError(f'{ip} is unreachable via HTTPS')


def check_if_ip_is_unreachable_via_https(ip: str, timeout: int):
    """
    Checks if IP address is unreachable via HTTPS protocol.
    :param ip: IP address to be checked; i.e. '192.168.255.129'
    :param timeout: time (in seconds) for IP address to become unreachable
    :raises ResultError: when IP address is reachable
    """
    log_debug(f'Checking if IP {ip} is unreachable via HTTPS')

    unreachable = wait_for(expected_value=False,
                           abort_if=None,
                           timeout=timeout,
                           callback=_is_ip_reachable_via_https,
                           raise_exc=False,
                           ip=ip)

    if not unreachable:
        raise ResultError(f'{ip} is reachable via HTTPS')


def _is_ip_reachable_via_https(ip: str) -> bool:
    try:
        response = get(f'https://{ip}', verify=False, timeout=1)
    except (ConnectionError, ReadTimeout, ChunkedEncodingError):
        return False

    return response.ok
